

// ── STATE ─────────────────────────────────────────
const KEY = 'fieldy_v2'
let state = JSON.parse(localStorage.getItem(KEY) || 'null') || {tasks:{now:[],today:[],later:[]},sites:[],people:[],focus:'',updated:null}
let apiKey = localStorage.getItem('fieldy_key') || ''
let currentScreen = 'home'
let actionCtx = null

const save = () => { localStorage.setItem(KEY, JSON.stringify(state)) }
const setState = (patch) => { Object.assign(state, patch, {updated: new Date().toISOString()}); save(); refreshBadges(); renderCurrentScreen() }

const ASSIGNEE = {uri:'אני',gio:"ג'יו",kenneth:"קנת'",asc:'ASC','11-16':'11-16'}
const STATUS_COLOR = {open:'red',pending:'orange',resolved:'green'}
const STATUS_LABEL = {open:'פתוח',pending:'ממתין',resolved:'נפתר'}

// ── NAVIGATION ────────────────────────────────────
const NAV_SCREENS = ['home','tasks','sites','people','tao']

document.querySelectorAll('.nav-btn').forEach(btn => {
  btn.addEventListener('click', () => {
    const s = btn.dataset.screen
    navigateTo(s)
  })
})

function navigateTo(screen, ctx=null) {
  if(ctx) actionCtx = ctx

  // Hide all screens
  document.querySelectorAll('.screen').forEach(s => s.classList.add('hidden'))
  
  // Show target
  document.getElementById('screen-' + screen).classList.remove('hidden')
  
  // Update nav
  document.querySelectorAll('.nav-btn').forEach(b => b.classList.remove('active'))
  const activeBtn = document.querySelector(`.nav-btn[data-screen="${screen}"]`)
  if(activeBtn) activeBtn.classList.add('active')
  
  // Show/hide nav
  document.getElementById('nav').style.display = NAV_SCREENS.includes(screen) ? 'grid' : 'none'
  
  currentScreen = screen
  renderCurrentScreen()
  
  // Scroll to top
  const el = document.getElementById('screen-' + screen)
  if(el) el.scrollTop = 0
}

function goBack() {
  navigateTo('home')
}


