async function doAnalyze() {
  const text = document.getElementById('input-text')?.value?.trim()
  const btn = document.getElementById('input-btn')
  const err = document.getElementById('input-error')
  if(!text || !apiKey) return
  btn.textContent = '⚙️ מסדר...'
  btn.style.background = '#1e293b'
  btn.style.color = '#475569'
  err.style.display = 'none'
  try {
    const parsed = await callClaude([{role:'user',content:text}], SYSTEM_PROMPT)
    const p = JSON.parse(parsed.replace(/```json|```/g,'').trim())
    const s = Date.now()
    const tag = (arr,pfx) => (arr||[]).map((t,i)=>({...t,id:`${pfx}${s}${i}`,done:false}))
    setState({
      tasks:{now:[...state.tasks.now,...tag(p.now,'n')],today:[...state.tasks.today,...tag(p.today,'d')],later:[...state.tasks.later,...tag(p.later,'l')]},
      sites: mergeSites(state.sites, p.sites||[]),
      people: mergePeople(state.people, p.people||[]),
      focus: p.focus || state.focus
    })
    navigateTo('home')
  } catch(e) {
    err.textContent = 'שגיאה: ' + e.message
    err.style.display = 'block'
    btn.textContent = '⚡ ארגן את היום'
    btn.style.background = 'linear-gradient(135deg,#3b82f6,#06b6d4)'
    btn.style.color = '#fff'
  }
}

