// ── CLAUDE API ────────────────────────────────────
const SYSTEM_PROMPT = `You are a field operations assistant for Uri, a Regional Manager at Innovative Agro Industry Philippines (Region II). Uri has ADHD. Engineers: Gio and Kenneth. Contractors: ASC Construction (engineer: Dave) and 11-16 Construction.
Uri sends notes in Hebrew/English/Tagalog mix. Return ONLY valid JSON (no markdown):
{"now":[{"id":"n1","text":"short task max 8 words","site":null,"assignee":"uri/gio/kenneth/asc/11-16 or null","color":"red/orange/green"}],"today":[...],"later":[...],"sites":[{"name":"site","province":"","issue":"","contractor":"asc/11-16 or null","status":"open/pending/resolved"}],"people":[{"name":"","role":"contractor/engineer/nia/other","company":"","pending":""}],"focus":"ONE Hebrew sentence"}
Rules: now MAX 3 tasks. color: red=critical, orange=important, green=routine.`

async function callClaude(messages, system=null) {
  const body = {model:'claude-sonnet-4-6',max_tokens:1500,messages}
  if(system) body.system = system
  const r = await fetch('https://api.anthropic.com/v1/messages',{
    method:'POST',
    headers:{'Content-Type':'application/json','x-api-key':apiKey,'anthropic-version':'2023-06-01','anthropic-dangerous-direct-browser-access':'true'},
    body:JSON.stringify(body)
  })
  const d = await r.json()
  if(d.error) throw new Error(d.error.message)
  return d.content?.find(b=>b.type==='text')?.text || ''
}

