function mergeSites(ex, inc) {
  const m={}; ex.forEach(s=>m[s.name]=s); inc.forEach(s=>m[s.name]={...(m[s.name]||{}),...s}); return Object.values(m)
}
function mergePeople(ex, inc) {
  const m={}; ex.forEach(p=>m[p.name]=p); inc.forEach(p=>m[p.name]={...(m[p.name]||{}),...p}); return Object.values(m)
}

